/* 仿微信日间 by water */
/* 感谢隱形線帮我找出了bug亚米亚米 */
/* 感谢砂砂老师提供的美化代码๑⁃̀⩊⁃́๑ */
/* 可以修改的地方用🩵标注啦 可以自己调适配 禁止二传 二改自用 */

/* ========================================= 【可直接调整区】底栏按钮位置与大小 ========================================= */
:root {
  /* --- 🩵底栏基础高度 --- */
  --chat-bottom-height: 60px;

  /* --- 🩵输入框 --- */
  --input-box-width: 240px;
  --input-box-height: 36px;
  --input-box-top: 10px;
  --input-box-left: 50px;
  --input-text-color: #1a1a1a;

  /* --- 🩵语音按钮（输入框内右侧） --- */
  --mic-width: 24px;
  --mic-height: 24px;
  --mic-top: 10px;
  --mic-right: 106px;

  /* --- 🩵表情按钮 --- */
  --sticker-width: 22px;
  --sticker-height: 22px;
  --sticker-top: 10px;
  --sticker-left: 298px;

  /* --- 🩵菜单/加号按钮 --- */
  --plus-width: 34px;
  --plus-height: 36px;
  --plus-top: 11px;
  --plus-left: 10px;

  /* --- 🩵AI等待回复按钮 --- */
  --ai-width: 38px;
  --ai-height: 38px;
  --ai-top: 8px;
  --ai-left: 340px;

  /* --- 🩵发送按钮（打字时显示） --- */
  --send-width: 60px;
  --send-height: 60px;
  --send-top: -7px;
  --send-left: 330px;

  /* --- 🩵打字时发送键左侧装饰图（仅装饰） --- */
  --dec-width: 35px;
  --dec-height: 35px;
  --dec-top: 12px;
  --dec-left: 295px;
}

/* ========================================= 仿微信顶栏 (Header) 深度定制 ========================================= */

.chat-header-custom {
  background-color: rgba(237, 237, 237, 0.85) !important;
  backdrop-filter: blur(12px) !important;
  -webkit-backdrop-filter: blur(12px) !important;
  border-bottom: 0.8px solid #d5d5d5 !important;
  border-top: none !important;
  border-left: none !important;
  border-right: none !important;
  height: 50px !important; /* 顶栏高度🩵 */
  min-height: 50px !important;
}

.header-profile-section {
  position: absolute !important;
  left: 50% !important;
  top: 50% !important;
  transform: translate(-50%, -50%) !important;
  margin-top: 0px !important; /* 🩵备注位置 */
  margin-left: 0px !important;
  justify-content: center !important;
  pointer-events: none !important;
}

.header-avatar-container,
.chat-header-subtitle {
  display: none !important;
}

.header-btn-back svg {
  display: none !important;
}
.header-btn-back {
  background-image: url("https://i.postimg.cc/s2fwKbb1/无标题183_20260222182046.png") !important;
  background-size: contain !important;
  background-repeat: no-repeat !important;
  background-position: center !important;
  width: 20px !important;
  height: 20px !important;
  position: relative !important;
  top: 0px !important;
  left: 4px !important;
  background-color: transparent !important;
  border: none !important;
}

.header-action-btn svg {
  opacity: 0 !important;
}

.header-action-btn:last-child {
  background-image: url("https://i.postimg.cc/W49SyXPw/无标题183_20260222181830.png") !important;
  background-size: contain !important;
  background-repeat: no-repeat !important;
  background-position: center !important;
  width: 24px !important;
  height: 24px !important;
  min-width: 24px !important;
  position: relative !important;
  top: 0px !important;
  right: 2px !important;
  background-color: transparent !important;
}

.chat-header-actions {
  gap: 12px !important;
  padding-right: 12px !important;
}

/* ========================================= 底栏背景与分割线 ========================================= */
.input-area-custom {
  background-color: rgba(247, 247, 247, 0.85) !important;
  backdrop-filter: blur(12px) !important;
  -webkit-backdrop-filter: blur(12px) !important;
  border-top: 0.8px solid #dedede !important;
  border-bottom: none !important;
  border-left: none !important;
  border-right: none !important;
  min-height: var(--chat-bottom-height) !important;
  box-shadow: none !important;
  position: relative !important;
}

.input-action-bar-custom,
.input-row-wrapper {
  background: transparent !important;
  border: none !important;
  box-shadow: none !important;
}

/* ========================================= 输入框本体 ========================================= */
textarea.input-box-custom,
.input-box-custom {
  width: var(--input-box-width) !important;
  height: var(--input-box-height) !important;
  min-height: var(--input-box-height) !important;
  background: #ffffff !important;
  background-color: #ffffff !important;
  box-shadow: inset 0 0 0 9999px #ffffff !important;
  border-radius: 6px !important;
  border: none !important;
  position: absolute !important;
  top: var(--input-box-top) !important;
  left: var(--input-box-left) !important;
  padding: 8px 36px 8px 10px !important;
  color: var(--input-text-color) !important;
  -webkit-text-fill-color: var(--input-text-color) !important;
  font-size: 15px !important;
  box-sizing: border-box !important;
  z-index: 20 !important;
}

textarea.input-box-custom::placeholder,
.input-box-custom::placeholder {
  color: transparent !important;
  -webkit-text-fill-color: transparent !important;
  opacity: 0 !important;
}

/* ========================================= 独立按钮替换与排版 (已修复菜单消失) ========================================= */

/* 1. 语音按钮 */
.input-btn-mic svg {
  display: none !important;
}
.input-btn-mic {
  width: var(--mic-width) !important;
  height: var(--mic-height) !important;
  position: absolute !important;
  top: var(--mic-top) !important;
  right: var(--mic-right) !important;
  background-image: url("https://i.postimg.cc/mgSGPfQy/无标题183_20260222183226.png") !important;
  background-size: contain !important;
  background-repeat: no-repeat !important;
  background-position: center !important;
  background-color: transparent !important;
  z-index: 30 !important;
  transform: scale(0.6) !important;
  opacity: 1 !important; /* 强制显示 */
  display: block !important;
}

/* 2. 表情按钮 */
.input-btn-sticker svg {
  display: none !important;
}
.input-btn-sticker {
  width: var(--sticker-width) !important;
  height: var(--sticker-height) !important;
  position: absolute !important;
  top: var(--sticker-top) !important;
  left: var(--sticker-left) !important;
  background-image: url("https://i.postimg.cc/yNYC9QPg/无标题183_20260222183223.png") !important;
  background-size: contain !important;
  background-repeat: no-repeat !important;
  background-position: center !important;
  background-color: transparent !important;
  z-index: 30 !important;
  opacity: 1 !important; /* 强制显示 */
  display: block !important;
}

/* 3. 菜单/加号按钮 (【核心修复】解除隐身术) */
.input-btn-plus svg {
  display: none !important;
}
.input-btn-plus {
  width: var(--plus-width) !important;
  height: var(--plus-height) !important;
  position: absolute !important;
  top: var(--plus-top) !important;
  left: var(--plus-left) !important;
  background-image: url("https://i.postimg.cc/P5MkCsmM/无标题183_20260222183224.png") !important;
  background-size: contain !important;
  background-repeat: no-repeat !important;
  background-position: center !important;
  background-color: transparent !important;
  border: none !important;
  z-index: 60 !important;
  opacity: 1 !important; /* 洗掉 icity 里的 opacity:0 */
  visibility: visible !important;
  display: block !important;
}

/* 4. 等待回复 (AI) 按钮 */
.input-btn-ai svg {
  display: none !important;
}
.input-btn-ai {
  width: var(--ai-width) !important;
  height: var(--ai-height) !important;
  min-width: var(--ai-width) !important;
  position: absolute !important;
  top: var(--ai-top) !important;
  left: var(--ai-left) !important;
  background-image: url("https://i.postimg.cc/cLcNvyQn/无标题183_20260222183221.png") !important;
  background-size: contain !important;
  background-repeat: no-repeat !important;
  background-position: center !important;
  background-color: transparent !important;
  border-radius: 0 !important;
  opacity: 1 !important;
  z-index: 51 !important;
  transition: opacity 0.2s !important;
  display: block !important;
}

/* 5. 发送按钮 */
.send-btn-custom svg {
  display: none !important;
}
.send-btn-custom {
  width: var(--send-width) !important;
  height: var(--send-height) !important;
  min-width: var(--send-width) !important;
  position: absolute !important;
  top: var(--send-top) !important;
  left: var(--send-left) !important;
  background-image: url("https://i.postimg.cc/7h4RCvXH/wu-biao-ti278-20260320120134.png") !important;
  background-size: contain !important;
  background-repeat: no-repeat !important;
  background-position: center !important;
  background-color: transparent !important;
  border: none !important;
  border-radius: 0 !important;
  z-index: 50 !important;
  opacity: 1 !important;
  display: block !important;
}

/* 打字时 发送键左侧装饰图 */
.input-area-custom:has(.input-box-custom:not(:placeholder-shown))::before {
  content: "" !important;
  position: absolute !important;
  width: var(--dec-width) !important;
  height: var(--dec-height) !important;
  top: var(--dec-top) !important;
  left: var(--dec-left) !important;
  background-image: url("https://i.postimg.cc/yNYC9QPg/无标题183_20260222183223.png") !important;
  background-size: contain !important;
  background-repeat: no-repeat !important;
  background-position: center !important;
  pointer-events: none !important;
  z-index: 40 !important;
}

/* 防卡死补丁 */
.input-area-custom:has(.input-box-custom:not(:placeholder-shown))
  .input-btn-ai {
  opacity: 0 !important;
  pointer-events: none !important;
}
.more-options-popup {
  z-index: 999999 !important;
}
.input-area-custom:has(.more-options-popup) .input-btn-ai,
.input-area-custom:has(.more-options-popup) .input-btn-plus,
.input-area-custom:has(.more-options-popup) .input-btn-sticker,
.input-area-custom:has(.more-options-popup) .input-btn-mic,
.input-area-custom:has(.more-options-popup) .send-btn-custom {
  pointer-events: none !important;
}

/* ========================================= 【修正】系统时间、系统提示框 (解决太长的问题) ========================================= */
.timestamp-custom,
.date-divider-custom,
.system-message-custom,
[class*="system-message"],
[class*="timestamp"],
[class*="date-divider"] {
  width: fit-content !important; /* 像微信一样紧贴文字宽度 */
  max-width: 80% !important;
  margin: 8px auto !important; /* 绝对居中 */

  background-color: #fcfcfc !important;
  border: 0.6px solid #e3e3e3 !important;
  color: #727272 !important;
  border-radius: 6px !important;
  padding: 2px 10px !important;

  display: block !important;
  text-align: center !important;
  box-sizing: border-box !important;
  font-size: 12px !important;
}
/* ========================================= 【可直接调整区】气泡小角 (带弧度三角) 设置 ========================================= */
:root {
  /* --- 我方气泡小角 (右侧绿色) --- */
  --me-tail-size: 9px; /* 决定小角的整体大小 */
  --me-tail-radius: 1.5px; /* 顶尖的圆角弧度 (您要求的4px) */
  --me-tail-top: 14px; /* 上下位置 */
  --me-tail-right: -4px; /* 左右位置 (负数代表往气泡外面移) */

  /* --- AI气泡小角 (左侧白色) --- */
  --them-tail-size: 9px; /* 决定小角的整体大小 */
  --them-tail-radius: 1.5px; /* 顶尖的圆角弧度 (您要求的4px) */
  --them-tail-top: 14px; /* 上下位置 */
  --them-tail-left: -4px; /* 左右位置 (负数代表往气泡外面移) */
}

/* ========================================= 1. 我方气泡 (绿色) ========================================= */
.bubble-me-custom {
  background-color: #95ec69 !important;
  background: #95ec69 !important;

  /* 更改后的内边距和圆角 */
  padding: 8px 12px !important;
  border-radius: 4px !important;

  position: relative !important;
  overflow: visible !important; /* 必须开启，允许小角溢出 */
  box-shadow: none !important;
  border: none !important;
  z-index: 1 !important; /* 建立层级，防止小角被背景吞掉 */
}

/* 强制我方气泡连发时不改变圆角 */
.bubble-me-custom.first,
.bubble-me-custom.mid,
.bubble-me-custom.last {
  border-radius: 4px !important;
}

/* 强制我方气泡内的文字颜色 */
.bubble-me-custom,
.bubble-me-custom * {
  color: #0f180a !important;
}

/* 我方气泡右侧小角 (带弧度的旋转正方形实现) */
.bubble-me-custom::after {
  content: "" !important;
  position: absolute !important;
  top: var(--me-tail-top) !important;
  right: var(--me-tail-right) !important;
  width: var(--me-tail-size) !important;
  height: var(--me-tail-size) !important;
  background-color: #95ec69 !important;

  /* 核心：倒角4px，并旋转45度，让右上角变成向右指的圆润尖角 */
  border-radius: var(--me-tail-radius) !important;
  transform: rotate(45deg) !important;
  -webkit-transform: rotate(45deg) !important;
  z-index: -1 !important; /* 放在气泡底层，无缝融合 */
}

/* ========================================= 2. AI / 对方气泡 (白色) ========================================= */
.bubble-them-custom {
  background-color: #ffffff !important;
  background: #ffffff !important;

  /* 更改后的内边距和圆角 */
  padding: 8px 12px !important;
  border-radius: 4px !important;

  position: relative !important;
  overflow: visible !important;
  box-shadow: none !important;
  border: none !important;
  z-index: 1 !important;
}

/* 强制对方气泡连发时不改变圆角 */
.bubble-them-custom.first,
.bubble-them-custom.mid,
.bubble-them-custom.last {
  border-radius: 4px !important;
}

/* 强制对方气泡内的文字颜色 */
.bubble-them-custom,
.bubble-them-custom * {
  color: #1a1a1a !important;
}

/* AI气泡左侧小角 (带弧度的旋转正方形实现) */
.bubble-them-custom::before {
  content: "" !important;
  position: absolute !important;
  top: var(--them-tail-top) !important;
  left: var(--them-tail-left) !important;
  width: var(--them-tail-size) !important;
  height: var(--them-tail-size) !important;
  background-color: #ffffff !important;

  /* 核心：倒角4px，并旋转45度，让左下角变成向左指的圆润尖角 */
  border-radius: var(--them-tail-radius) !important;
  transform: rotate(45deg) !important;
  -webkit-transform: rotate(45deg) !important;
  z-index: -1 !important; /* 放在气泡底层，无缝融合 */
}
/* ========================================= 3. 特殊消息自动隐藏气泡与小角 (表情包/图片/转账等) ========================================= */

/* 当气泡内包含：图片(含表情包)、视频、图片容器、转账卡片、位置卡片、长图卡片、礼物盒 时，强制背景透明并去掉内边距 */
.bubble-me-custom:has(
    img,
    video,
    .msg-image-wrapper,
    .msg-transfer-card,
    .msg-loc-card,
    .msg-sim-card,
    .gift-ig-container
  ),
.bubble-them-custom:has(
    img,
    video,
    .msg-image-wrapper,
    .msg-transfer-card,
    .msg-loc-card,
    .msg-sim-card,
    .gift-ig-container
  ) {
  background-color: transparent !important;
  background: transparent !important;
  padding: 0 !important;
  border: none !important;
  box-shadow: none !important;
}

/* 强制隐藏我方特殊消息的气泡小角 */
.bubble-me-custom:has(
    img,
    video,
    .msg-image-wrapper,
    .msg-transfer-card,
    .msg-loc-card,
    .msg-sim-card,
    .gift-ig-container
  )::after {
  display: none !important;
}

/* 强制隐藏对方特殊消息的气泡小角 */
.bubble-them-custom:has(
    img,
    video,
    .msg-image-wrapper,
    .msg-transfer-card,
    .msg-loc-card,
    .msg-sim-card,
    .gift-ig-container
  )::before {
  display: none !important;
}

